public boolean shouldPrintMessage(int timestamp, String message) {
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (timestamp < 0) {
        throw new IllegalArgumentException("Timestamp cannot be negative");
    }

    // Assuming a map to store the last printed timestamp for each message
    Map<String, Integer> messageTimestamps = new HashMap<>();

    // Check if the message has been printed before
    if (messageTimestamps.containsKey(message)) {
        int lastPrintedTimestamp = messageTimestamps.get(message);
        // If the last printed timestamp is more than or equal to 10 seconds ago, print the message
        if (timestamp - lastPrintedTimestamp >= 10) {
            messageTimestamps.put(message, timestamp);
            return true;
        } else {
            return false;
        }
    } else {
        // If the message has never been printed, print it and store the timestamp
        messageTimestamps.put(message, timestamp);
        return true;
    }
}

