    if (b == null) {
        throw new NullPointerException("The byte array to write cannot be null");
    }
    if (b.length == 0) {
        return; // No-op for zero-length array
    }
    try {
        for (int i = 0; i < b.length; i++) {
            write(b[i]);
        }
    } catch (IOException e) {
        throw e;
    } catch (Exception e) {
        throw new IOException("An error occurred while writing to the output stream", e);
    }
}

