private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null || end < 0 || end >= headerPart.length()) {
        return -1; // Invalid input, return -1 to indicate no valid \r\n found
    }

    int length = headerPart.length();
    for (int i = end; i < length - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i; // Return the index of \r
        }
    }

    return -1; // No \r\n sequence found
}

