public static long factorial(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Factorial is not defined for negative numbers.");
    }
    if (n == 0 || n == 1) {
        return 1;
    }
    long result = 1;
    for (int i = 2; i <= n; i++) {
        result *= i;
        if (result < 0) { // Check for overflow
            throw new ArithmeticException("Factorial result exceeds the maximum value for long.");
        }
    }
    return result;
}

