protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, 0.0, Collections.emptyList());
    }

    List<E> pathEdges = new ArrayList<>(tour);
    V startVertex = null;
    Map<V, V> vertexPredecessorMap = new HashMap<>();

    // Find a starting vertex and construct the predecessor map
    for (E edge : pathEdges) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        if (!vertexPredecessorMap.containsKey(target)) {
            vertexPredecessorMap.put(target, source);
        }

        if (!vertexPredecessorMap.containsKey(source)) {
            startVertex = source;
        }
    }

    if (startVertex == null) {
        throw new IllegalArgumentException("Invalid tour: No starting vertex found");
    }

    // Reconstruct the path
    List<V> pathVertices = new ArrayList<>();
    V currentVertex = startVertex;
    while (currentVertex != null) {
        pathVertices.add(currentVertex);
        currentVertex = vertexPredecessorMap.get(currentVertex);
    }

    // Ensure the path is closed
    if (!pathVertices.get(0).equals(pathVertices.get(pathVertices.size() - 1))) {
        throw new IllegalArgumentException("Invalid tour: Tour is not closed");
    }

    double pathWeight = 0.0;
    for (E edge : pathEdges) {
        pathWeight += graph.getEdgeWeight(edge);
    }

    return new GraphPathImpl<>(graph, startVertex, pathWeight, pathVertices);
}

