    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    boolean escaped = false;

    for (int i = 0; i < str.length(); i++) {
        char currentChar = str.charAt(i);

        if (escaped) {
            switch (currentChar) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\"':
