protected int removeUnusedNodes() {
    int removedCount = 0;
    try {
        // Assuming there is a method to get the root of the category tree
        CategoryNode rootNode = getCategoryTreeRoot();

        // Use a queue for BFS traversal
        Queue<CategoryNode> queue = new LinkedList<>();
        queue.add(rootNode);

        while (!queue.isEmpty()) {
            CategoryNode currentNode = queue.poll();

            // Check if the current node is inactive
            if (!currentNode.isActive()) {
                // Remove the node from its parent
                currentNode.getParent().removeChild(currentNode);
                removedCount++;
            } else {
                // Add all active children to the queue for further processing
                for (CategoryNode childNode : currentNode.getChildren()) {
                    queue.add(childNode);
                }
            }
        }
    } catch (Exception e) {
        // Handle any exceptions that might occur during node removal
        e.printStackTrace();
    }
    return removedCount;
}

